 "content": "from math import gcd
from functools import reduce


def transform(grid):
    h, w = len(grid), len(grid[0])
    coords = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    colored = [(r, c) for r in range(h) for c in range(w) if grid[r][c] not in (0, 8)]
    if not coords or not colored:
        return [row[:] for row in grid]

    # The colored motif is rotated clockwise and enlarged into square tiles
    # that occupy the large 8-shaped mask.
    rr = [r for r, _ in coords]
    cc = [c for _, c in coords]
    tile_runs = []
    for r in range(min(rr), max(rr) + 1):
        run = 0
        for c in range(min(cc), max(cc) + 2):
            if c <= max(cc) and grid[r][c] == 8:
                run += 1
            elif run:
                tile_runs.append(run)
                run = 0
    for c in range(min(cc), max(cc) + 1):
        run = 0
        for r in range(min(rr), max(rr) + 2):
            if r <= max(rr) and grid[r][c] == 8:
                run += 1
            elif run:
                tile_runs.append(run)
                run = 0
    scale = reduce(gcd, tile_runs)

    r0, r1 = min(r for r, _ in colored), max(r for r, _ in colored)
    c0, c1 = min(c for _, c in colored), max(c for _, c in colored)
    motif = [[grid[r][c] for c in range(c0, c1 + 1)] for r in range(r0, r1 + 1)]
    rotated = [list(row) for row in zip(*motif[::-1])]

    out = [row[:] for row in grid]
    for tr, row in enumerate(rotated):
        for tc, color in enumerate(row):
            if color == 0:
                continue
            top, left = min(rr) + tr * scale, min(cc) + tc * scale
            for r in range(top, top + scale):
                for c in range(left, left + scale):
                    if r < h and c < w and grid[r][c] == 8:
                        out[r][c] = color
    return out


if __name__ == '__main__':
    import sys, json
    print(json.dumps(transform(json.load(sys.stdin))))
